using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
public static class DesertWideRidgeRouteSetup {
 const string Marker="work/wide-ridge-route-v3.txt";
 [InitializeOnLoadMethod]static void Init(){EditorApplication.delayCall+=Once;EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredEditMode)EditorApplication.delayCall+=Once;};}
 static void Once(){if(!EditorApplication.isPlayingOrWillChangePlaymode&&!File.Exists(Marker))Apply();}
 static List<Vector3> Smooth(Vector3[] guide){var path=new List<Vector3>{guide[0]};for(int i=0;i<guide.Length-1;i++){var a=guide[Mathf.Max(0,i-1)];var b=guide[i];var c=guide[i+1];var d=guide[Mathf.Min(guide.Length-1,i+2)];for(int j=1;j<=80;j++){float t=j/80f;path.Add(.5f*(2*b+(-a+c)*t+(2*a-5*b+4*c-d)*t*t+(-a+3*b-3*c+d)*t*t*t));}}return path;}
 static void Apply(){var previous=SceneManager.GetActiveScene();var scene=SceneManager.GetSceneByPath("Assets/Scenes/Demo.unity");bool opened=!scene.isLoaded;if(opened)scene=EditorSceneManager.OpenScene("Assets/Scenes/Demo.unity",OpenSceneMode.Additive);RouteTerrainBumps bumps=null;try{
 var car=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CarPathFollower>(true)).Single();var terrain=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Terrain>(true)).First();var root=scene.GetRootGameObjects().Single(g=>g.name=="CarPath").transform;bumps=root.GetComponent<RouteTerrainBumps>();if(!bumps)bumps=root.gameObject.AddComponent<RouteTerrainBumps>();
 Directory.CreateDirectory("work/WideRidgeRouteBackup");if(!File.Exists("work/WideRidgeRouteBackup/Demo.unity"))EditorSceneManager.SaveScene(scene,"work/WideRidgeRouteBackup/Demo.unity",true);
 var start=car.points.First(p=>p).position;var origin=terrain.transform.position;
 Vector2[] layout={new Vector2(95.17f,55.03f),new Vector2(160f,80f),new Vector2(175f,155f),new Vector2(110f,200f),new Vector2(25f,230f),new Vector2(25f,310f),new Vector2(105f,345f),new Vector2(175f,385f),new Vector2(160f,465f),new Vector2(80f,470f),new Vector2(20f,415f)};
 var guide=layout.Select(p=>origin+new Vector3(p.x,start.y-origin.y,p.y)).ToArray();guide[0]=start;var dense=Smooth(guide);var distances=new List<float>{0};for(int i=1;i<dense.Count;i++)distances.Add(distances.Last()+Vector3.Distance(dense[i-1],dense[i]));float length=distances.Last();var final=new Vector3[20];int index=1;
 for(int i=0;i<20;i++){float distance=length*i/19;while(index<distances.Count-1&&distances[index]<distance)index++;float t=(distance-distances[index-1])/Mathf.Max(.001f,distances[index]-distances[index-1]);final[i]=Vector3.Lerp(dense[index-1],dense[index],t);}
 var actual=Smooth(new[]{car.transform.position}.Concat(final).ToArray());var size=terrain.terrainData.size;foreach(var p in actual){var local=p-origin;if(local.x<5||local.z<5||local.x>size.x-5||local.z>size.z-5)throw new Exception("Smoothed driving path leaves terrain at "+p);}
 float minSpacing=float.PositiveInfinity,maxTurn=0,minTurn=float.PositiveInfinity;int straight=0,maxStraight=0;bool left=false,right=false;
 for(int i=1;i<20;i++){minSpacing=Mathf.Min(minSpacing,Vector3.Distance(final[i-1],final[i]));if(i<19){float angle=Vector3.SignedAngle(final[i]-final[i-1],final[i+1]-final[i],Vector3.up);left|=angle< -5;right|=angle>5;maxTurn=Mathf.Max(maxTurn,Mathf.Abs(angle));minTurn=Mathf.Min(minTurn,Mathf.Abs(angle));straight=Mathf.Abs(angle)<2?straight+1:0;maxStraight=Mathf.Max(maxStraight,straight);}}
 if(minSpacing<40||maxTurn>85||!left||!right||maxStraight>2)throw new Exception("Route variation validation failed spacing="+minSpacing+" turn="+maxTurn);
 var points=new Transform[20];for(int i=0;i<20;i++){points[i]=i<car.points.Length&&car.points[i]?car.points[i]:new GameObject("RoutePoint "+(i+1).ToString("00")).transform;points[i].SetParent(root,true);Undo.RecordObject(points[i],"Spread route across map");points[i].position=final[i];points[i].name="RoutePoint "+(i+1).ToString("00");points[i].SetSiblingIndex(i);EditorUtility.SetDirty(points[i]);}car.points=points;EditorUtility.SetDirty(car);
 Undo.RecordObject(bumps,"Space and reshape terrain ridges");bumps.route=car;bumps.terrains=new[]{terrain};bumps.spacing=110;bumps.minimumWorldSeparation=65;bumps.halfWidth=15;bumps.halfLength=5;bumps.minimumHeight=.4f;bumps.maximumHeight=.7f;bumps.endClearance=75;EditorUtility.SetDirty(bumps);
 var centers=bumps.GetBumpCenters();float minGap=float.PositiveInfinity;for(int i=0;i<centers.Length;i++)for(int j=0;j<i;j++)minGap=Mathf.Min(minGap,Vector3.ProjectOnPlane(centers[i]-centers[j],Vector3.up).magnitude);if(centers.Length<4||minGap<64.9f)throw new Exception("Bumps too close or missing");
 // Render an actual generated terrain ridge, then restore the saved terrain asset before saving the scene.
 var original=terrain.terrainData;bumps.RebuildTerrain();try{var center=centers[0];center.y=terrain.SampleHeight(center)+terrain.transform.position.y;var cameraObject=new GameObject("Temporary ridge preview camera");cameraObject.hideFlags=HideFlags.HideAndDontSave;var camera=cameraObject.AddComponent<Camera>();var target=new RenderTexture(1024,768,24);try{camera.transform.position=center+new Vector3(15,7,-17);camera.transform.LookAt(center+Vector3.up*.15f);camera.fieldOfView=48;camera.nearClipPlane=.1f;camera.farClipPlane=150;camera.clearFlags=CameraClearFlags.Skybox;camera.targetTexture=target;camera.Render();var previousTarget=RenderTexture.active;RenderTexture.active=target;var image=new Texture2D(1024,768,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1024,768),0,0);image.Apply();File.WriteAllBytes("work/sand-ridge-preview.png",image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);RenderTexture.active=previousTarget;}finally{camera.targetTexture=null;target.Release();UnityEngine.Object.DestroyImmediate(target);UnityEngine.Object.DestroyImmediate(cameraObject);}}finally{bumps.RestoreTerrain();}if(terrain.terrainData!=original)throw new Exception("Original terrain was not restored");
 EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();File.WriteAllText(Marker,"20 route points across map; guide arc spacing="+(length/19).ToString("F1")+"m; minimum anchor spacing="+minSpacing.ToString("F1")+"m; turns="+minTurn.ToString("F1")+".."+maxTurn.ToString("F1")+" degrees, both left and right; longest straight run="+maxStraight+". Bumps="+centers.Length+"; along-route gaps about 103..123m; minimum world separation="+minGap.ToString("F1")+"m. Curved asymmetric sand ridges; original TerrainData unchanged. Actual driven spline checked inside terrain.");Selection.activeGameObject=root.gameObject;SceneView.RepaintAll();
 }catch(Exception ex){File.WriteAllText("work/wide-ridge-route-error.txt",ex.ToString());Debug.LogException(ex);}finally{if(bumps)bumps.RestoreTerrain();if(previous.IsValid()&&previous.isLoaded)SceneManager.SetActiveScene(previous);if(opened)EditorSceneManager.CloseScene(scene,true);}}
}

